import os, json
from pathlib import Path
async def main(args):
    """目录 mtime 快照：{相对路径(posix): mtime}。排除 .git/__pycache__/嵌套git仓库；
    path 非空时只扫该子目录（相对 workspace），文件键也带该前缀（diff 时两份快照同源可直接比对）。"""
    p = args.params
    root = (p.get("path") or ".").strip() or "."
    base = Path(".").resolve()
    target = (base / root).resolve() if root != "." else base
    try:
        target.relative_to(base)
    except ValueError:
        return {"snap": "{}", "error": f"路径越界: {root}"}
    EXCLUDE = {".git", "__pycache__"}
    snap = {}
    for cur, dirs, files in os.walk(target):
        dirs[:] = [d for d in dirs if d not in EXCLUDE and not (Path(cur) / d / ".git").exists()]
        for f in files:
            fp = Path(cur) / f
            try:
                rel = fp.relative_to(base).as_posix()
                snap[rel] = fp.stat().st_mtime
            except OSError:
                pass
    return {"snap": json.dumps(snap)}
